@router.get("/{mission_id}/match")
def match_preview(
    mission_id: UUID,
    scope: Scope,
    user: Annotated[AppUser, Depends(get_current_user)],
) -> MatchPreview:
    mission = scope.get(Mission, mission_id)
    if mission.lead_id != user.id:
        raise Forbidden(user.role, "Directors and leads run the matcher only on their own missions")
    if mission.status != MissionStatus.DRAFT:
        logger.info("match preview rejected: mission %s is %s", mission.id, mission.status)
        raise HTTPException(
            409, f"Mission is {mission.status}. The matcher preview is allowed only in DRAFT."
        )
    slots = mission_out(scope, mission).slots
    rows = scope.session.execute(
        scope.select(CrewSkill)
        .add_columns(AppUser)
        .join(AppUser, (AppUser.org_id == CrewSkill.org_id) & (AppUser.id == CrewSkill.user_id))
        .where(AppUser.role == UserRole.CREW)
    ).all()
    users: dict[UUID, AppUser] = {}
    skills: dict[UUID, dict[UUID, int]] = {}
    holders: dict[UUID, int] = {}
    for cs, u in rows:
        users[u.id] = u
        skills.setdefault(u.id, {})[cs.skill_id] = cs.level
        holders[cs.skill_id] = holders.get(cs.skill_id, 0) + 1

    def overlaps(m):
        return (m.start_date <= mission.end_date) & (mission.start_date <= m.end_date)

    busy = set(
        scope.session.scalars(
            scope.select(Unavailability)
            .where(overlaps(Unavailability))
            .with_only_columns(Unavailability.user_id)
        )
    )
    busy |= set(
        scope.session.scalars(
            scope.select(Assignment)
            .join(
                Mission,
                (Mission.org_id == Assignment.org_id) & (Mission.id == Assignment.mission_id),
            )
            .where(
                Assignment.status.in_([AssignmentStatus.INVITED, AssignmentStatus.ACCEPTED]),
                overlaps(Mission),
            )
            .with_only_columns(Assignment.user_id)
        )
    )
    busy |= set(
        scope.session.scalars(
            scope.select(Assignment)
            .where(
                Assignment.mission_id == mission.id,
                Assignment.status == AssignmentStatus.DECLINED,
            )
            .with_only_columns(Assignment.user_id)
        )
    )
    window = timedelta(days=WORKLOAD_WINDOW_DAYS)
    booked: dict[UUID, list[tuple[date, date]]] = {}
    for uid, start, end in scope.session.execute(
        scope.select(Assignment)
        .join(
            Mission, (Mission.org_id == Assignment.org_id) & (Mission.id == Assignment.mission_id)
        )
        .where(
            Assignment.status.in_([AssignmentStatus.INVITED, AssignmentStatus.ACCEPTED]),
            Mission.start_date <= mission.end_date + window,
            Mission.end_date >= mission.start_date - window,
        )
        .with_only_columns(Assignment.user_id, Mission.start_date, Mission.end_date)
    ):
        booked.setdefault(uid, []).append((start, end))
    candidates = [
        Candidate(
            uid,
            users[uid].username,
            sk,
            workload_days(mission.start_date, mission.end_date, booked.get(uid, [])),
        )
        for uid, sk in skills.items()
        if uid not in busy
    ]
    matches = []
    for slot, c in zip(slots, assign(slots, candidates, holders), strict=True):
        suggestion = c and CrewSuggestion(
            user_id=c.user_id,
            username=c.username,
            display_name=users[c.user_id].display_name,
            level=c.skills[slot.skill_id],
            workload_days=c.workload_days,
        )
        matches.append(SlotMatch(slot=slot, suggestion=suggestion))
    return MatchPreview(mission_id=mission.id, slots=matches)

import random
import time
from datetime import date
from uuid import UUID, uuid4

from mc_shared import SlotOut

EVA = UUID(int=1)
ROBOTICS = UUID(int=2)
PILOTING = UUID(int=3)
GEOLOGY = UUID(int=4)
WELDING = UUID(int=5)
NAMES = {
    EVA: "EVA",
    ROBOTICS: "Robotics",
    PILOTING: "Piloting",
    GEOLOGY: "Geology",
    WELDING: "Welding",
}


def slot(skill, level, position=1):
    return SlotOut(
        id=uuid4(), position=position, skill_id=skill, skill_name=NAMES[skill], min_level=level
    )


def crew(name, skills, workload_days=0):
    from mc_api.matcher import Candidate

    return Candidate(uuid4(), name, {k: v for k, v in skills.items()}, workload_days)


def holders_of(candidates):
    out = {}
    for c in candidates:
        for skill in c.skills:
            out[skill] = out.get(skill, 0) + 1
    return out


def run(slots, candidates):
    from mc_api.matcher import assign

    return assign(slots, candidates, holders_of(candidates))


def names(result):
    return [c.username if c else None for c in result]


def test_assign_prefers_the_lowest_gap_ac11_dev_over_cara():
    got = run([slot(EVA, 3)], [crew("dev", {EVA: 3}), crew("cara", {EVA: 4})])
    assert names(got) == ["dev"]


def test_assign_closest_fit_wins_ac12():
    got = run(
        [slot(PILOTING, 3)],
        [crew("ava", {PILOTING: 5}), crew("ivan", {PILOTING: 4}), crew("ben", {PILOTING: 3})],
    )
    assert names(got) == ["ben"]


def test_assign_below_minimum_or_other_skill_gives_none_ac7():
    got = run([slot(EVA, 3)], [crew("dev", {EVA: 2}), crew("jo", {GEOLOGY: 4})])
    assert got == [None]


def test_assign_greedy_trap_ac11():
    got = run(
        [slot(EVA, 3, 1), slot(ROBOTICS, 3, 2)],
        [crew("cara", {EVA: 3, ROBOTICS: 3}), crew("dev", {EVA: 4})],
    )
    assert names(got) == ["dev", "cara"]


def test_assign_fills_the_maximum_number_of_slots_ac11():
    got = run(
        [slot(EVA, 3, 1), slot(EVA, 3, 2), slot(EVA, 3, 3)],
        [crew("abe", {EVA: 3}), crew("bob", {EVA: 3})],
    )
    assert sorted(n for n in names(got) if n) == ["abe", "bob"]
    assert names(got).count(None) == 1


def test_assign_uses_each_member_one_time():
    got = run([slot(EVA, 3, 1), slot(EVA, 3, 2)], [crew("abe", {EVA: 3}), crew("bob", {EVA: 3})])
    assert sorted(names(got)) == ["abe", "bob"]


def test_assign_full_tie_goes_to_the_first_username_ac16():
    eli, abe = crew("eli", {EVA: 3}), crew("abe", {EVA: 3})
    from mc_api.matcher import assign

    for order in ([eli, abe], [abe, eli]):
        assert names(assign([slot(EVA, 3)], order, holders_of(order))) == ["abe"]


def test_assign_handles_empty_inputs():
    assert run([], [crew("abe", {EVA: 3})]) == []
    assert run([slot(EVA, 3)], []) == [None]


def test_assign_scales_to_20_slots_and_200_candidates():
    slots = [slot(EVA, 1, p) for p in range(1, 21)]
    candidates = [
        crew(f"u{i:03}", {EVA: i % 5 + 1}, workload_days=(i * 7) % 301) for i in range(200)
    ]
    start = time.monotonic()
    got = run(slots, candidates)
    assert time.monotonic() - start < 2
    assert len({c.user_id for c in got}) == 20
